/* ── VISUAL NOVEL OVERLAY ──────────────────────────── */
.vn-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  background: #101010;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.45s ease;
}
.vn-overlay.active {
  opacity: 1;
  pointer-events: all;
}

/* ── SCENE ─────────────────────────────────────────── */
.vn-scene {
  flex: 1;
  position: relative;
  overflow: hidden;
  background: #0f0f0f;
}
.vn-scene::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(to bottom, rgba(0,0,0,0.28), rgba(0,0,0,0.48)),
    radial-gradient(circle at 28% 28%, rgba(255,255,255,0.04), transparent 30%);
  pointer-events: none;
}
/* Background image */
.vn-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
  opacity: 0.55;
  filter: brightness(0.5) blur(1px);
}

