/* Corner screws -- dark on light bezel */
.vn-screw {
  position: absolute;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #888, #444);
  border: 1px solid rgba(0,0,0,0.25);
  z-index: 8;
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.2),
    0 1px 2px rgba(0,0,0,0.3);
}
.vn-screw::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(45deg);
  width: 6px;
  height: 1.5px;
  background: rgba(0,0,0,0.35);
  border-radius: 1px;
}
.vn-screw-tl {
  top: 12px;
  left: 14px;
}
.vn-screw-tr {
  top: 12px;
  right: 14px;
}
.vn-screw-bl {
  bottom: 36px;
  left: 14px;
}
.vn-screw-br {
  bottom: 36px;
  right: 14px;
}

/* ── SCREEN AREA ────────────────────────────────────── */
.vn-screen {
  top: 22px;
  left: 22px;
  right: 22px;
  bottom: 36px;
  background: #071510;
  border-radius: 2px;
  overflow: hidden;
  box-shadow: /* Outer recess shadow -- thick dark line on all sides */
    0 0 0 2px rgba(0,0,0,0.45),
    /* Deep inner shadow on top/left -- light comes from top-right */
    inset 4px 4px 12px rgba(0,0,0,0.7),
    inset -1px -1px 6px rgba(0,0,0,0.3),
    /* Screen glow radiating outward through the bezel */
    0 0 0 4px rgba(74,124,94,0.08),
    0 0 24px rgba(74,124,94,0.2),
    0 0 56px rgba(74,124,94,0.12);
  position: absolute;
}
/* Scene illustration fills the screen */
.vn-board-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0;
  transition: opacity 0.7s ease;
  border-radius: 0;
  margin: 0;
}
.vn-board-img.loaded {
  opacity: 0.5;
}
/* Screen content overlay gradient */
.vn-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    160deg,
    rgba(5,18,16,0.55) 0%,
    rgba(5,18,16,0.1) 45%,
    rgba(5,18,16,0.72) 100%
  );
  z-index: 1;
  pointer-events: none;
}
/* Glare streak -- diagonal highlight */
.vn-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(255,255,255,0.04) 0%,
    rgba(255,255,255,0) 55%
  );
  z-index: 2;
  pointer-events: none;
  top: -30%;
  left: -5%;
  width: 50%;
  height: 60%;
  transform: rotate(-8deg);
  border-radius: 50%;
}
/* Screen inner glow border */
.vn-screen-inner-border {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(74,124,94,0.25);
  z-index: 3;
  pointer-events: none;
  border-radius: 3px;
}

/* ── SCREEN TEXT CONTENT ────────────────────────────── */
.vn-board-label, .vn-board-text, .vn-board-loading {
  position: relative;
  z-index: 4;
}
.vn-board-label {
  font-family: "Source Code Pro", monospace;
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(168, 213, 181, 0.8);
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 20px 24px 0;
  margin: 0;
  margin-bottom: 10px;
}
/* Active indicator dot */
.vn-board-label::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #5ab07a;
  box-shadow: 0 0 8px rgba(90,176,122,0.8), 0 0 16px rgba(90,176,122,0.4);
  flex-shrink: 0;
  animation: ledPulse 2.5s ease-in-out infinite;
}
@keyframes ledPulse {
  0%, 100% { box-shadow: 0 0 6px rgba(90,176,122,0.7), 0 0 14px rgba(90,176,122,0.35); }
    50%       { box-shadow: 0 0 10px rgba(90,176,122,1),   0 0 22px rgba(90,176,122,0.6); }
}
.vn-board-loading {
  font-family: "Source Code Pro", monospace;
  font-size: 0.78rem;
  color: rgba(168, 213, 181, 0.6);
  letter-spacing: 0.06em;
  position: relative;
  top: 44px;
  left: 22px;
  z-index: 4;
  text-shadow: 0 1px 4px rgba(0,0,0,0.8);
  padding: 10px 24px 0;
}

/* ── CONTROL RAIL (bottom strip) ────────────────────── */
.vn-control-rail {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 40px;
  background: linear-gradient(180deg, #b8b4ac 0%, #a4a09a 50%, #aeaaa2 100%);
  border-top: 1px solid rgba(0,0,0,0.15);
  border-radius: 0 0 12px 12px;
  display: flex;
  align-items: center;
  padding: 0 18px;
  gap: 7px;
  z-index: 5;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.35),
    inset 0 -1px 0 rgba(0,0,0,0.1);
}
/* Power / status lights on control rail */
.vn-light {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid rgba(0,0,0,0.15);
  flex-shrink: 0;
  box-shadow: 0 0 5px rgba(90,176,122,0.8);
  background: #5ab07a;
}
.vn-light.dim {
  background: #888;
  box-shadow: none;
  border: 1px solid rgba(0,0,0,0.2);
}
/* USB port */
.vn-usb {
  margin-left: auto;
  width: 16px;
  height: 9px;
  border-radius: 2px;
  background: #8a8680;
  border: 1.5px solid #7a7670;
  box-shadow: inset 0 1px 1px rgba(0,0,0,0.2);
}
/* Brand label */
.vn-brand {
  font-family: "Source Code Pro", monospace;
  font-size: 0.52rem;
  letter-spacing: 0.14em;
  color: rgba(0,0,0,0.3);
  text-transform: uppercase;
  margin-left: 10px;
}

