/* ── FOCUS STYLES ──────────────────────────────────── */
/* Remove default outline and replace with visible ring */
:focus-visible {
  outline: 3px solid #a8d5b5;
  outline-offset: 3px;
  border-radius: 4px;
}
/* Buttons inside dark VN overlay need different focus */
.vn-overlay :focus-visible {
  outline-color: #a8d5b5;
}
/* Skip to main content — shown only for keyboard focus */
.skip-link {
  position: fixed;
  top: 8px;
  left: 50%;
  z-index: 10000;
  transform: translate(-50%, calc(-100% - 20px));
  opacity: 0;
  pointer-events: none;
  background: var(--forest);
  color: #d4edd9;
  font-family: "Nunito", sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 10px 18px;
  border-radius: var(--radius);
  text-decoration: none;
  transition: transform 0.18s ease, opacity 0.18s ease;
}
.skip-link:focus-visible {
  transform: translate(-50%, 0);
  opacity: 1;
  pointer-events: auto;
  outline: 3px solid #a8d5b5;
  outline-offset: 3px;
}
.skip-link:focus:not(:focus-visible) {
  transform: translate(-50%, calc(-100% - 20px));
  opacity: 0;
  pointer-events: none;
}

/* ── VN KEYBOARD SUPPORT ───────────────────────────── */
/* Make dialogue box focusable and show focus state */
.vn-dialogue:focus {
  outline: none;
}
.vn-dialogue:focus-visible {
  outline: 3px solid #a8d5b5;
  outline-offset: -3px;
}
/* Larger touch target for advance hint area */
.vn-advance {
  font-family: "Source Code Pro", monospace;
  font-size: 0.92rem;
  color: rgba(185,230,200,0.92);
  letter-spacing: 0.08em;
  animation: blink 1.2s infinite;
  display: none;
  z-index: 6;
  margin-top: 14px;
  align-self: flex-end;
  padding: 10px 4px 4px;
  cursor: pointer;
}

