/* ── PERSISTENT BADGE ───────────────────────────────── */
.pixel-badge {
  display: flex;
  position: fixed;
  bottom: 80px;
  right: 16px;
  z-index: 90;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  transition: transform 0.2s ease;
}
.pixel-badge:hover {
  transform: scale(1.08);
  box-shadow: 0 4px 14px rgba(30,61,41,0.3);
}
.pixel-badge:active {
  transform: scale(0.96);
}
.pixel-badge-portrait {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2.5px solid var(--forest-mid);
  object-fit: cover;
  object-position: top center;
  background: var(--forest-light);
  box-shadow: 0 3px 10px rgba(30,61,41,0.3);
  display: block;
  transition: border-color 0.3s ease;
}
.pixel-badge-portrait.reacting {
  border-color: var(--amber);
  animation: badgePulse 0.5s ease;
}
@keyframes badgePulse {
  0%   { transform: scale(1); }
    40%  { transform: scale(1.15); }
    100% { transform: scale(1); }
}
/* Fallback SVG badge when images not ready */
.pixel-badge-fallback {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 2.5px solid var(--forest-mid);
  background: var(--forest-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  box-shadow: 0 3px 10px rgba(30,61,41,0.3);
}
.pixel-badge-label {
  font-family: "Source Code Pro", monospace;
  font-size: 0.55rem;
