  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: var(--chalk);
  border: 1px solid var(--border);
  border-radius: 99px;
  padding: 1px 7px;
  white-space: nowrap;
  box-shadow: 0 1px 3px rgba(42,31,20,0.08);
}

/* ── COACH CARD POP-IN ──────────────────────────────── */
.pixel-coach-card {
  position: fixed;
  right: -340px;
  /* starts off screen */
  bottom: 140px;
  width: 300px;
  background: var(--chalk);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: -4px 4px 20px rgba(42,31,20,0.15);
  z-index: 95;
  display: flex;
  gap: 10px;
  padding: 12px 14px;
  transition: right 0.4s cubic-bezier(0.34,1.2,0.64,1);
  pointer-events: none;
}
.pixel-coach-card.visible {
  right: 16px;
  pointer-events: all;
}
.pixel-coach-portrait {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--forest-mid);
  object-fit: cover;
  object-position: top center;
  background: var(--forest-light);
  flex-shrink: 0;
  display: block;
}
.pixel-coach-fallback {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--forest-mid);
  background: var(--forest-light);
  display: flex;
  align-items: center;
  justify-content: center;
