  font-size: 0.72rem;
  font-weight: 700;
  color: var(--forest-dark);
  margin-bottom: 4px;
}
/* Speech bubble tail pointing right toward badge */
.pixel-coach-card::after {
  content: "";
  position: absolute;
  right: -8px;
  bottom: 20px;
  width: 0;
  height: 0;
  border-top: 8px solid transparent;
  border-bottom: 8px solid transparent;
  border-left: 8px solid var(--border);
}
.pixel-coach-card::before {
  content: "";
  position: absolute;
  right: -6px;
  bottom: 21px;
  width: 0;
  height: 0;
  border-top: 7px solid transparent;
  border-bottom: 7px solid transparent;
  border-left: 7px solid var(--chalk);
  z-index: 1;
}
.pixel-coach-dismiss {
  position: absolute;
  top: 6px;
  right: 8px;
  background: none;
  border: none;
  font-size: 0.7rem;
  color: var(--ink-muted);
  cursor: pointer;
  padding: 2px 4px;
  line-height: 1;
  transition: color 0.15s;
}
.pixel-coach-dismiss:hover {
  color: var(--ink);
}

