/* ── BLOCK 1 ── */

/* ── Babbage-as-machine visual layer ─────────────────── */

.babbage-avatar {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #101a14;
  border: 2px solid #4a7c5e;
  color: #a8d5b5;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Source Code Pro", monospace;
  font-size: 14px;
  flex-shrink: 0;
  margin-top: 2px;
}

/* ── VN prediction choice overlay ───────────────────── */
.vn-prediction-note {
  margin-top: 10px;
  font-family: "Source Code Pro", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  color: rgba(240,237,232,0.7);
  text-transform: uppercase;
}

/* ── Sprint 2A: S1 problem artifact + prompt ingredients ───────── */

.ingredient-heading {
  font-family: "Source Code Pro", monospace;
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  margin-bottom: 8px;
}
.ingredient-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ingredient-chip {
  border: 1.5px solid var(--border-strong);
  background: var(--cream);
  color: var(--ink-light);
  border-radius: 999px;
  padding: 4px 9px;
  font-size: 0.72rem;
  font-weight: 700;
  transition: all 0.18s ease;
}
.ingredient-chip.covered {
  background: var(--forest);
  border-color: var(--forest-dark);
  color: #d4edd9;
}

/* ── S1 cleaned consultation result card ───────────────────── */

.s1-result-card {
  max-width: 760px;
  margin: 8px auto 14px;
  background: var(--chalk);
  border: 1.5px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: 2px 4px 12px rgba(42,31,20,0.08);
  padding: 18px 20px;
  animation: slideUp 0.28s ease forwards;
}
.s1-result-eyebrow {
  font-family: "Source Code Pro", monospace;
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--forest-dark);
  margin-bottom: 6px;
}
.s1-result-title {
  font-family: "Fraunces", serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
  margin-bottom: 10px;
}
.s1-result-body {
  font-size: 0.86rem;
  line-height: 1.7;
  color: var(--ink-mid);
}
.s1-result-body h1, .s1-result-body h2, .s1-result-body h3, .s1-result-body strong {
  color: var(--forest-dark);
}
/* S1 focused result mode */
.s1-result-controls-sub {
  font-size: 0.78rem;
  color: #4a3728;
  font-weight: 700;
  margin-top: 2px;
}
.s1-secondary-btn:hover {
  border-color: var(--forest-mid);
  color: var(--forest-dark);
}

