/* ── BLOCK 3 ── */

/* Sprint 2A rewrite: S1 section-review needs room to breathe. Shocking development. */
#inputContainer {
  flex-shrink: 0;
  max-height: min(54vh, 620px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  border-top: 2px solid var(--border);
}

/* ── BLOCK 4 ── */
/* Sprint 2B: Babbage gets a home. Placeholder shelf layout, not final art. */
.vn-overlay.active.babbage-consult .vn-scene {
  background: radial-gradient(circle at 18% 45%, rgba(168,213,181,0.13), transparent 28%),
    radial-gradient(circle at 82% 36%, rgba(100,190,255,0.14), transparent 30%),
    linear-gradient(120deg, #111712 0%, #151b19 48%, #0f1720 100%);
}
/* Keep the smartboard present, but stop it from stealing the whole scene. */
.vn-overlay.active.babbage-consult .vn-smartboard-wrap {
  left: 27%;
  top: 5%;
  width: 40%;
  opacity: 0.86;
  transform: scale(0.96);
  transform-origin: center top;
}
/* Pixel becomes the left-side mentor anchor. */
.vn-overlay.active.babbage-consult .vn-character {
  left: 2.5%;
  right: auto;
  bottom: -8px;
  height: 58%;
  justify-content: flex-start;
  transform: translateX(-12px);
}
.vn-overlay.active.babbage-consult .vn-character.visible {
  transform: translateX(0);
}
.vn-overlay.active.babbage-consult #vnPortrait {
  object-position: left bottom;
}
/* Babbage shelf placeholder */
.babbage-shelf {
  position: absolute;
  right: 3.5%;
  top: 8%;
  width: min(30vw, 390px);
  height: min(56vh, 520px);
  z-index: 3;
  opacity: 0;
  transform: translateX(18px) scale(0.98);
  transition: opacity 0.45s ease, transform 0.45s ease, filter 0.45s ease;
  pointer-events: none;
  filter: drop-shadow(0 20px 45px rgba(0,0,0,0.55));
}
.vn-overlay.active.babbage-consult .babbage-shelf {
  opacity: 1;
  transform: translateX(0) scale(1);
}
.babbage-shelf-inner {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 18px;
  border: 2px solid rgba(104,165,196,0.35);
  background: linear-gradient(180deg, rgba(12,24,31,0.86), rgba(8,15,22,0.92)),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.035), rgba(255,255,255,0.035) 1px, transparent 1px, transparent 18px);
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.06),
    inset 0 -30px 55px rgba(0,0,0,0.35),
    0 0 30px rgba(77,174,220,0.10);
}
.babbage-shelf-label {
  position: absolute;
  top: 12px;
  left: 14px;
  right: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: "Source Code Pro", monospace;
  font-size: 0.6rem;
  letter-spacing: 0.13em;
  color: rgba(177,226,245,0.75);
  text-transform: uppercase;
}
.babbage-status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: rgba(94,165,196,0.5);
  box-shadow: 0 0 10px rgba(94,165,196,0.35);
}
.babbage-crt {
  position: absolute;
  left: 14%;
  right: 14%;
  top: 17%;
  height: 30%;
  border-radius: 16px 16px 10px 10px;
  border: 2px solid rgba(180,214,226,0.22);
  background: linear-gradient(145deg, #1e2a2f, #0a1115);
  box-shadow: 0 12px 25px rgba(0,0,0,0.55);
}
.babbage-crt::before {
  content: "";
  position: absolute;
  inset: 12% 10%;
  border-radius: 10px;
  background: repeating-linear-gradient(0deg, rgba(178,235,255,0.07), rgba(178,235,255,0.07) 1px, transparent 1px, transparent 5px),
    radial-gradient(circle at 50% 45%, rgba(120,215,255,0.25), rgba(20,71,93,0.28) 45%, rgba(5,18,24,0.9));
  border: 1px solid rgba(139,217,245,0.28);
  box-shadow: inset 0 0 20px rgba(91,205,255,0.18);
}
.babbage-crt::after {
  content: "BABBAGE NODE";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 12px;
  text-align: center;
  font-family: "Source Code Pro", monospace;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  color: rgba(177,226,245,0.72);
}
.babbage-bookshelf {
  position: absolute;
  left: 10%;
  right: 10%;
  bottom: 16%;
  height: 30%;
  border-top: 3px solid rgba(176,132,82,0.42);
  border-bottom: 4px solid rgba(84,55,31,0.55);
}
.babbage-book {
  position: absolute;
  bottom: 8px;
  width: 10%;
  border-radius: 4px 4px 1px 1px;
  background: linear-gradient(180deg, rgba(116,168,132,0.9), rgba(38,82,58,0.95));
  box-shadow: inset 2px 0 0 rgba(255,255,255,0.12);
}
.babbage-book.b1 {
  left: 6%;
  height: 78%;
}
.babbage-book.b2 {
  left: 19%;
  height: 58%;
  background: linear-gradient(180deg, rgba(178,144,79,0.92), rgba(91,63,28,0.95));
}
.babbage-book.b3 {
  left: 32%;
  height: 88%;
  background: linear-gradient(180deg, rgba(98,155,190,0.92), rgba(35,75,100,0.96));
}
.babbage-book.b4 {
  left: 46%;
  height: 68%;
  background: linear-gradient(180deg, rgba(142,112,170,0.92), rgba(68,47,91,0.96));
}
.babbage-book.b5 {
  left: 61%;
  height: 80%;
  background: linear-gradient(180deg, rgba(188,111,82,0.92), rgba(103,49,32,0.96));
}
.babbage-card-stack {
  position: absolute;
  right: 8%;
  bottom: 11%;
  width: 25%;
  height: 15%;
  transform: rotate(-5deg);
}
.babbage-card-stack span {
  position: absolute;
  inset: 0;
  border-radius: 5px;
  background: rgba(238,230,205,0.86);
  border: 1px solid rgba(87,70,42,0.35);
  box-shadow: 0 5px 10px rgba(0,0,0,0.25);
}
.babbage-card-stack span:nth-child(2) {
  transform: translate(-7px, 7px) rotate(-4deg);
  opacity: 0.88;
}
.babbage-card-stack span:nth-child(3) {
  transform: translate(-13px, 13px) rotate(-8deg);
  opacity: 0.72;
}
.babbage-response-slot {
  position: absolute;
  left: 11%;
  right: 11%;
  bottom: 5%;
  min-height: 34px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(0,0,0,0.28);
  border: 1px solid rgba(139,217,245,0.20);
  color: rgba(177,226,245,0.82);
  font-family: "Source Code Pro", monospace;
  font-size: 0.58rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-align: center;
}
.babbage-shelf.thinking .babbage-shelf-inner {
  animation: babbageShelfPulse 1.35s ease-in-out infinite;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.07),
    0 0 38px rgba(99,204,255,0.28);
}
.babbage-shelf.thinking .babbage-status-dot, .babbage-shelf.responding .babbage-status-dot {
  background: #9ee7ff;
  box-shadow: 0 0 18px rgba(158,231,255,0.9);
}
.babbage-shelf.responding .babbage-crt::before {
  box-shadow: inset 0 0 30px rgba(125,228,255,0.45), 0 0 26px rgba(125,228,255,0.32);
}
.babbage-shelf.responding .babbage-response-slot::after {
  content: "analysis ready";
}
@keyframes babbageShelfPulse {
  0%, 100% { filter: brightness(1); }
    50% { filter: brightness(1.22); }
}

