.vn-overlay.active .vn-skip,
#vnOverlay .vn-skip,
#vnOverlay.active .vn-skip {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}


.vn-overlay, #vnOverlay, .vn-scene{
  max-width: none !important;
  max-height: none !important;
  transform: none !important;
  overflow: hidden !important;
}

/* Keep normal Professor Pixel scenes visible. */
.vn-overlay.active:not(.babbage-terminal-consult):not(.babbage-terminal-textmode):not(.babbage-prediction):not(.pc-clean-prediction):not(.pc-clean-output) .vn-smartboard-wrap,
.vn-overlay.active:not(.babbage-terminal-consult):not(.babbage-terminal-textmode):not(.babbage-prediction):not(.pc-clean-prediction):not(.pc-clean-output) .vn-character {
  opacity: 1 !important;
  visibility: visible !important;
}

/* Gently reduce ONLY the Babbage computer/consultation scene.
   This avoids the black empty VN stage problem because it does not scale
   the entire overlay, scene, dialogue, or regular intro screens. */
