/* ══════════════════════════════════════════════════════
   V136 — Reflection Room restored after active CSS pruning
   This interface is created/controlled by app.js, so its selectors cannot
   be detected reliably by an index-only unused-CSS scan.
   ══════════════════════════════════════════════════════ */
.reflection-overlay {
  position: fixed;
  inset: 0;
  z-index: 3000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(20px, env(safe-area-inset-top)) 16px max(20px, env(safe-area-inset-bottom));
  background:
    radial-gradient(ellipse at 25% 20%, rgba(74, 124, 94, 0.18), transparent 55%),
    radial-gradient(ellipse at 75% 80%, rgba(196, 124, 45, 0.12), transparent 55%),
    rgba(21, 45, 31, 0.97);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  overflow-y: auto;
  transition: opacity 0.25s ease, visibility 0s linear 0.25s;
}

.reflection-overlay.visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity 0.25s ease;
}

.reflection-room {
  width: min(100%, 680px);
  max-height: min(92vh, 900px);
  overflow-y: auto;
  padding: 32px;
  background: var(--ref-paper, #f7f4ee);
  border: 2px solid var(--ref-border, #d6cfc0);
  border-radius: var(--radius-lg, 12px);
  color: var(--ref-ink, #2c2416);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.42);
  scrollbar-width: thin;
  scrollbar-color: var(--ref-input-bdr, #c8bfaa) var(--ref-paper, #f7f4ee);
  -webkit-overflow-scrolling: touch;
}

.ref-eyebrow {
  margin-bottom: 10px;
  color: #6f573b;
  font-family: "Source Code Pro", monospace;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-align: center;
  text-transform: uppercase;
}

.ref-title {
  margin-bottom: 10px;
  color: var(--ref-ink, #2c2416);
  font-family: "Lora", Georgia, serif;
  font-size: clamp(1.35rem, 3vw, 1.75rem);
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
}

.ref-subtitle {
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--ref-border, #d6cfc0);
  color: #514733;
  font-family: "Lora", Georgia, serif;
  font-size: 1rem;
  line-height: 1.65;
  text-align: center;
}

.ref-question {
