/* V137 — Runtime images and audio reorganized under assets/ with centralized JS paths. */


/* ══════════════════════════════════════════════════════
   SHARED VN SECONDARY CHARACTER SLOT
   Character identity is supplied by JavaScript. This slot is reusable for
   Jordan and future students; it does not own dialogue or scene geometry.
   ══════════════════════════════════════════════════════ */
.vn-student-character {
  position: absolute;
  display: flex;
  align-items: flex-end;
  justify-content: flex-start;
  z-index: 6;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease, filter .2s ease;
}
.vn-student-character.visible {
  opacity: 1;
}
#vnStudentPortrait {
  height: 100%;
  width: auto;
  object-fit: contain;
  object-position: left bottom;
  filter: drop-shadow(0 16px 30px rgba(0,0,0,.46));
  transition: opacity .12s ease;
}

/* Workstation/analysis scenes are single-character by design. A scenario that
   needs a different speaker places that character in the primary S1 slot. */
.vn-overlay.babbage-terminal-consult .vn-student-character,
.vn-overlay.babbage-terminal-textmode .vn-student-character,
.vn-overlay.babbage-prediction .vn-student-character,
.vn-overlay.pc-clean-prediction .vn-student-character,
.vn-overlay.pc-prediction-result .vn-student-character {
  display: none !important;
}

/* ══════════════════════════════════════════════════════
   V139 — SILENT START + AUDIO PREFERENCE ONBOARDING
   ══════════════════════════════════════════════════════ */
.audio-setup-overlay {
  position: fixed;
  inset: 0;
  z-index: 2147483646 !important;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px max(24px, env(safe-area-inset-bottom));
  overflow-y: auto;
  background:
    radial-gradient(ellipse at 22% 18%, rgba(74, 124, 94, 0.24) 0%, transparent 52%),
    radial-gradient(ellipse at 78% 82%, rgba(196, 124, 45, 0.14) 0%, transparent 52%),
    rgba(35, 55, 43, 0.96);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease;
}

.audio-setup-overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.audio-setup-modal {
  position: relative;
  width: min(94vw, 650px);
  padding: 34px 36px 30px;
  color: #1f160f;
  background: #fffdf8;
  border: 2px solid #c9b99d;
  border-radius: 18px;
  box-shadow: 0 20px 56px rgba(0, 0, 0, 0.38);
  text-align: left;
}

.audio-setup-pixel {
  position: absolute;
  top: -5px;
  right: 22px;
  width: 132px;
  height: 126px;
  overflow: hidden;
  pointer-events: none;
  z-index: 2;
}

.audio-setup-pixel img {
  position: absolute;
  top: 0;
  left: 50%;
  display: block;
  width: 132px;
  max-width: none;
  height: auto;
  transform: translateX(-50%);
}

.audio-setup-speaker {
  margin: 0 148px 6px 0;
  font: 800 0.78rem/1.2 "Nunito", system-ui, sans-serif;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #2d6a47;
}

.audio-setup-title {
  max-width: 520px;
  margin: 0 126px 10px 0;
  font: 800 clamp(1.35rem, 3vw, 1.75rem)/1.28 "Lora", Georgia, serif;
  color: #1f160f;
}

.audio-setup-help {
  max-width: 560px;
  margin: 0 0 22px;
  font: 600 0.98rem/1.5 "Nunito", system-ui, sans-serif;
  color: #5f4937;
}

.audio-choice-fieldset {
  display: grid;
  gap: 12px;
  margin: 0;
  padding: 0;
  border: 0;
}

.audio-choice-card {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 13px;
  align-items: start;
  min-height: 76px;
  padding: 15px 16px;
  background: #fffaf2;
  border: 2px solid #c9b99d;
  border-radius: 12px;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.audio-choice-card:hover {
  border-color: #5c8b6c;
  background: #f8fff9;
  transform: translateY(-1px);
}

.audio-choice-card:has(input:checked) {
  background: #eef8f1;
  border-color: #245f3f;
  box-shadow: 0 0 0 3px rgba(45, 106, 71, 0.16);
}

.audio-choice-card:has(input:focus-visible) {
  box-shadow: 0 0 0 4px rgba(45, 106, 71, 0.24);
}

.audio-choice-card input {
  width: 20px;
  height: 20px;
  margin: 3px 0 0;
  accent-color: #245f3f;
}

.audio-choice-copy {
  display: grid;
  gap: 3px;
}

.audio-choice-copy strong {
  font: 800 1.02rem/1.25 "Nunito", system-ui, sans-serif;
  color: #1f160f;
}

.audio-choice-copy span {
  font: 600 0.92rem/1.42 "Nunito", system-ui, sans-serif;
  color: #5f4937;
}

.audio-setup-primary {
  width: 100%;
  min-height: 54px;
  margin-top: 20px;
  padding: 13px 18px;
  font: 800 1.02rem/1.2 "Nunito", system-ui, sans-serif;
  color: #ffffff;
  background: #245f3f;
  border: 2px solid #123d29;
  border-radius: 10px;
  cursor: pointer;
}

.audio-setup-primary:hover:not(:disabled),
.audio-setup-primary:focus-visible:not(:disabled) {
  background: #123d29;
  box-shadow: 0 0 0 4px rgba(45, 106, 71, 0.22);
}

.audio-setup-primary:disabled {
  color: #6b6259;
  background: #ddd6ca;
  border-color: #b9ad9b;
  cursor: not-allowed;
}

.audio-setup-cancel {
  display: block;
  margin: 12px auto 0;
  padding: 8px 12px;
  font: 800 0.92rem/1.2 "Nunito", system-ui, sans-serif;
  color: #5f4937;
  background: transparent;
  border: 0;
  border-radius: 7px;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.audio-setup-cancel:hover,
.audio-setup-cancel:focus-visible {
  color: #1f160f;
  background: rgba(45, 90, 61, 0.08);
}

body.pc-audio-setup-open {
  overflow: hidden;
}

body #musicToggle.voices-only {
