/* ══════════════════════════════════════════════════════
   V446 — TEACHING PROGRESS HUD
   One UI typeface, three text tiers, stronger level progress, and a compact
   Babbage detail panel. PromptCraft's brand face remains separate by design.
   ══════════════════════════════════════════════════════ */
.pc-progress-menu {
  position: relative;
  min-width: 0;
  z-index: 80;
  font-family: "Nunito", Arial, sans-serif;
}
.pc-progress-menu > summary { list-style: none; }
.pc-progress-menu > summary::-webkit-details-marker { display: none; }

.pc-progress-menu .header-status {
  cursor: pointer;
  display: grid !important;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  column-gap: 12px !important;
  min-width: min(430px, 38vw);
  min-height: 72px;
  padding: 10px 13px;
  border: 1px solid rgba(108, 190, 229, .7);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(20, 79, 132, .86), rgba(8, 40, 80, .96));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.09), 0 3px 10px rgba(0,0,0,.16);
  color: #fff;
}
.pc-progress-menu .header-status:hover,
.pc-progress-menu .header-status:focus-visible,
.pc-progress-menu[open] .header-status {
  border-color: #79c5e8;
  background: linear-gradient(180deg, rgba(24, 92, 151, .94), rgba(9, 45, 89, .99));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.11), 0 0 0 2px rgba(230,165,29,.14);
  outline: none;
}

/* Tier 2: compact supporting UI labels. */
.pc-progress-level-badge,
.pc-progress-summary-kicker,
.pc-progress-menu .xp-label,
.pc-progress-view-label,
.pc-progress-caret,
.pc-progress-eyebrow,
.pc-progress-level-number,
.pc-progress-total,
.pc-progress-next,
.pc-progress-scenarios,
.pc-progress-lifetime,
.pc-progress-note,
.pc-progress-engine-figure figcaption {
  font-family: "Nunito", Arial, sans-serif !important;
  font-style: normal !important;
}

.pc-progress-level-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 64px;
  min-height: 44px;
  padding: 8px 10px;
  border-radius: 10px 10px 14px 14px;
  border: 1px solid rgba(230,165,29,.82);
  background: linear-gradient(180deg, rgba(230,165,29,.14), rgba(230,165,29,.07));
  color: #ffe7a8;
  font-size: .76rem;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .02em;
  text-transform: uppercase;
  white-space: nowrap;
}
.pc-progress-summary-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}
.pc-progress-summary-kicker {
  color: #a8d9ef;
  font-size: .68rem;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .08em;
  text-transform: uppercase;
}

/* Tier 1: the current educator level is the primary information. */
.pc-progress-menu .level-tag {
  min-width: 0;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  color: #fffdf8 !important;
  font-family: "Nunito", Arial, sans-serif !important;
  font-size: 1.04rem !important;
  font-weight: 900 !important;
  line-height: 1.12 !important;
  letter-spacing: 0 !important;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pc-progress-menu .xp-group {
  display: grid !important;
  grid-template-columns: minmax(150px, 1fr) auto;
  align-items: center;
  gap: 9px !important;
  margin-top: 4px;
}
.pc-progress-menu .xp-label {
  color: #e1f0f7 !important;
  font-size: .72rem !important;
  font-weight: 900 !important;
  line-height: 1 !important;
  letter-spacing: .01em;
  white-space: nowrap;
}
.pc-progress-menu .xp-track {
  position: relative;
  display: block;
  width: 100% !important;
  min-width: 150px;
  height: 14px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(2,18,39,.96), rgba(18,59,96,.92));
  border: 1px solid rgba(170, 218, 239, .52);
  border-radius: 999px;
  box-shadow: inset 0 3px 5px rgba(0,0,0,.46), inset 0 0 0 1px rgba(255,255,255,.035), 0 1px 0 rgba(255,255,255,.04);
}
.pc-progress-menu .xp-track::after {
  content: '';
  position: absolute;
  inset: 1px 2px auto;
  height: 4px;
  border-radius: 999px;
  background: rgba(255,255,255,.12);
  pointer-events: none;
}
.pc-progress-menu .xp-fill {
  display: block;
  height: 100%;
  width: 0;
  background: linear-gradient(180deg, #ffe28d 0%, #e6a51d 58%, #b97605 100%) !important;
  border-radius: inherit;
  box-shadow: 0 0 11px rgba(230,165,29,.52), inset 0 1px 0 rgba(255,255,255,.42);
  transition: width .4s ease;
}
.pc-progress-view-label {
  color: #f2f7fa;
  font-size: .72rem;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}
.pc-progress-caret {
  color: #ffd66f;
  font-size: .78rem;
  font-weight: 900;
  line-height: 1;
  transition: transform .18s ease;
}
.pc-progress-menu[open] .pc-progress-caret { transform: rotate(180deg); }

/* Expanded progress panel uses the same restrained type system. */
.pc-progress-panel {
  position: absolute;
  top: calc(100% + 9px);
  right: 0;
  width: min(390px, calc(100vw - 24px));
  padding: 0;
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid #63b8e1;
  background: #0b274d;
  color: #f7fbfd;
  box-shadow: 0 22px 56px rgba(4, 16, 36, .42);
  z-index: 400;
}
.pc-progress-panel::before {
  content: '';
  position: absolute;
  right: 24px;
  top: -7px;
  width: 12px;
  height: 12px;
  background: #0d315d;
  border-left: 1px solid #63b8e1;
  border-top: 1px solid #63b8e1;
  transform: rotate(45deg);
}
.pc-progress-panel-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 15px 12px;
  background: linear-gradient(135deg, #0d315d 0%, #124b7b 100%);
  border-bottom: 2px solid #e6a51d;
}
.pc-progress-eyebrow {
  color: #a8d9ef;
  font-size: .68rem;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: .08em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.pc-progress-panel h2 {
  margin: 0;
  color: #fffdf8;
  font-family: "Nunito", Arial, sans-serif;
  font-size: 1.1rem;
  font-weight: 900;
  line-height: 1.12;
}
.pc-progress-level-number {
  flex: 0 0 auto;
  padding: 6px 9px;
  border-radius: 8px;
  background: rgba(230,165,29,.12);
  color: #ffe09a;
  border: 1px solid rgba(230,165,29,.7);
  font-size: .72rem;
  font-weight: 900;
  line-height: 1;
  text-transform: uppercase;
}
.pc-progress-panel-body {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 13px;
  align-items: start;
  padding: 14px 15px 13px;
}
.pc-progress-engine-figure {
  margin: 0;
  border: 1px solid rgba(137,197,224,.48);
  border-radius: 9px;
  background: #eaf4f9;
  overflow: hidden;
}
.pc-progress-engine-figure img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: center;
  mix-blend-mode: multiply;
}
.pc-progress-engine-figure figcaption {
  padding: 5px 6px 6px;
  color: #173b61;
  background: #f6fbfd;
  font-size: .66rem;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;
}
.pc-progress-details p {
  margin: 0 0 9px;
  color: #dcebf3;
  font-family: "Nunito", Arial, sans-serif;
  font-size: .78rem;
  font-weight: 700;
  line-height: 1.4;
}
.pc-progress-next {
  color: #ffd775;
  font-size: .76rem;
  font-weight: 900;
  line-height: 1.25;
  margin-bottom: 4px;
}
.pc-progress-total {
  color: #f5fbfe;
  font-size: .72rem;
  font-weight: 900;
  line-height: 1.2;
  margin-bottom: 6px;
}
.pc-progress-full-track {
  height: 13px;
  overflow: hidden;
  border-radius: 999px;
  background: #061a34;
  border: 1px solid rgba(159,214,239,.52);
  box-shadow: inset 0 2px 4px rgba(0,0,0,.42);
  margin-bottom: 9px;
}
.pc-progress-full-track span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(180deg, #ffe28d 0%, #e6a51d 58%, #b97605 100%);
  box-shadow: 0 0 10px rgba(230,165,29,.42), inset 0 1px 0 rgba(255,255,255,.36);
  transition: width .45s ease;
}
.pc-progress-scenarios,
.pc-progress-lifetime {
  font-size: .7rem;
  font-weight: 800;
  line-height: 1.3;
}
.pc-progress-scenarios { color: #c2deeb; margin-bottom: 3px; }
.pc-progress-lifetime { color: #94bfd4; }
.pc-progress-note {
  margin: 0;
  padding: 9px 15px 11px;
  border-top: 1px solid rgba(136,193,220,.22);
  background: rgba(3,18,39,.35);
  color: #b5cfdd;
  font-size: .68rem;
  font-weight: 700;
  line-height: 1.38;
}
.pc-progress-note strong { color: #f5fbfe; font-weight: 900; }

@media (max-width: 1000px) {
  .pc-progress-view-label { display: none; }
  .pc-progress-menu .header-status {
    grid-template-columns: auto minmax(0, 1fr) auto;
    min-width: min(360px, 44vw);
  }
}
@media (max-width: 820px) {
  .pc-progress-menu { width: min(100%, 370px); }
  .pc-progress-menu .header-status { min-width: 0; width: 100%; }
  .pc-progress-panel { right: 50%; transform: translateX(50%); }
  .pc-progress-panel::before { right: 50%; margin-right: -6px; }
}
@media (max-width: 520px) {
  .pc-progress-menu .header-status {
    grid-template-columns: auto minmax(0, 1fr) auto;
    min-height: 64px;
    padding: 8px 9px;
    column-gap: 9px !important;
  }
  .pc-progress-level-badge {
    min-width: 53px;
    min-height: 38px;
    padding: 6px 7px;
    font-size: .68rem;
  }
  .pc-progress-summary-kicker { font-size: .61rem; }
  .pc-progress-menu .level-tag { font-size: .91rem !important; }
  .pc-progress-menu .xp-group { grid-template-columns: minmax(96px, 1fr) auto; gap: 7px !important; }
  .pc-progress-menu .xp-track { min-width: 96px; height: 12px; }
  .pc-progress-menu .xp-label { font-size: .66rem !important; }
  .pc-progress-panel { width: min(380px, calc(100vw - 16px)); }
  .pc-progress-panel-body { grid-template-columns: 78px minmax(0, 1fr); gap: 10px; padding: 12px; }
  .pc-progress-panel-heading { padding: 12px; }
  .pc-progress-panel h2 { font-size: 1rem; }
  .pc-progress-note { padding: 8px 12px 10px; }
}

