/* SOURCE: src/css/scenarios/shared.css */
/* ══════════════════════════════════════════════════════
   PROMPTCRAFT V271 — SHARED SCENARIO SYSTEM
   One component vocabulary and one fluid type scale for S1–S8. Scenario
   content may differ, but mission cards, activity cards, choices, feedback,
   buttons, checkpoints, and VN dialogue now resize through the same tokens.
   ══════════════════════════════════════════════════════ */

:root {
  /* Pixel units keep the shared scale independent from legacy root-font breakpoints. */
  --pc-type-xs: clamp(11.5px, calc(11px + 0.09vw), 12.8px);
  --pc-type-small: clamp(13.1px, calc(12.5px + 0.13vw), 14.7px);
  --pc-type-body: clamp(15.5px, calc(14.9px + 0.15vw), 17.3px);
  --pc-type-control: clamp(16px, calc(15.4px + 0.12vw), 17.3px);
  --pc-type-label: clamp(14.7px, calc(13.8px + 0.18vw), 16.6px);
  --pc-type-card-title: clamp(18.4px, calc(16.3px + 0.42vw), 24px);
  --pc-type-mission-title: clamp(26.4px, calc(21.8px + 0.88vw), 37.6px);
  --pc-type-dialogue: clamp(16px, calc(15px + 0.18vw), 18px);
  --pc-type-speaker: clamp(18px, calc(16.3px + 0.30vw), 22px);
  --pc-type-board: clamp(15.2px, calc(14.1px + 0.20vw), 18px);
  --pc-leading-body: 1.58;
  --pc-leading-tight: 1.22;
  --pc-stage-pad-inline: clamp(10px, 2vw, 24px);
  --pc-stage-pad-block: clamp(12px, 2vw, 24px);
  --pc-card-pad: clamp(18px, 2.6vw, 34px);
}

/* Shared mission typography across guided, activity, and development screens. */
.scenario-mission .mission-eyebrow,
.s1-clean-eyebrow,
.pc-activity-kicker,
.pc-shell-status {
  font-size: var(--pc-type-small) !important;
  line-height: var(--pc-leading-tight) !important;
}

.scenario-mission .mission-title,
body.s1-active:not(.s1-result-active) .s1-clean-mission .mission-title {
  font-size: var(--pc-type-mission-title) !important;
  line-height: 1.12 !important;
}

.scenario-mission .mission-copy,
body.s1-active:not(.s1-result-active) .s1-clean-mission .mission-copy,
.pc-shell-copy,
.pc-shell-note,
.pc-shell-loop {
  font-size: var(--pc-type-body) !important;
  line-height: var(--pc-leading-body) !important;
}

/* One reusable activity workspace for current and future scenarios. */
body.pc-scenario-activity-active .chat-area,
body.pc-scenario-activity-active #chat {
  display: none !important;
}

body.pc-scenario-activity-active #inputContainer {
  flex: 1 1 auto;
  min-height: 0;
  max-height: none !important;
  overflow-y: auto !important;
  border-top: 0 !important;
  background: var(--cream);
}

.pc-scenario-workbench {
  display: flex;
  flex-direction: column;
  background: var(--cream);
  font-size: var(--pc-type-body);
}

.pc-scenario-stage {
  width: min(100%, 1500px);
  margin: 0 auto;
  padding: var(--pc-stage-pad-block) var(--pc-stage-pad-inline) clamp(28px, 4vw, 44px);
}

.pc-scenario-progress {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(6px, 1vw, 10px);
  margin-top: 13px;
}

.pc-scenario-progress span {
  border: 1px solid rgba(255,255,255,.4);
  border-radius: 999px;
  padding: 5px 10px;
  font-size: var(--pc-type-xs);
  line-height: 1.25;
  letter-spacing: .04em;
  color: rgba(255,255,255,.82);
}

.pc-scenario-progress span.active {
  background: #fff;
  color: var(--forest-dark);
  font-weight: 800;
}

.pc-activity-card{
  background: #fffdf9;
  border: 1.5px solid var(--border-strong);
  border-radius: 16px;
  box-shadow: 0 12px 30px rgba(45,34,20,.08);
}

.pc-activity-card h2{
  font-family: "Lora", Georgia, serif;
  color: var(--forest-dark);
  font-size: var(--pc-type-card-title);
  line-height: 1.25;
  margin: 5px 0 10px;
}

.pc-activity-card p,
.pc-choice-copy,
.pc-choice-body {
  font-size: var(--pc-type-body);
}

.pc-activity-standby {
  margin-top: 14px;
  padding: var(--pc-card-pad);
  text-align: center;
}

.pc-activity-kicker {
  font-family: "Source Code Pro", monospace;
  color: var(--terracotta);
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}


.pc-activity-task {
  padding: var(--pc-card-pad);
}

.pc-activity-instruction {
  margin: 0 0 18px;
  color: var(--ink-light);
  line-height: var(--pc-leading-body);
}

.pc-choice-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 310px), 1fr));
  gap: clamp(10px, 1.4vw, 14px);
}

.pc-choice-card {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border: 1.5px solid var(--border);
  border-radius: 12px;
  background: #fff;
  padding: clamp(12px, 1.5vw, 15px);
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease, box-shadow .16s ease;
}

.pc-choice-card:hover {
  border-color: var(--forest-mid);
  transform: translateY(-1px);
  box-shadow: 0 7px 18px rgba(45,90,61,.09);
}

.pc-choice-card.selected {
  border-color: var(--forest-mid);
  background: var(--forest-light);
  box-shadow: inset 0 0 0 1px var(--forest-mid);
}

.pc-choice-card:has(input:focus-visible) {
  outline: 4px solid rgba(196,124,45,.35);
  outline-offset: 2px;
}

.pc-choice-card input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.pc-choice-marker {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: var(--parchment);
  color: var(--forest-dark);
  font-family: "Source Code Pro", monospace;
  font-size: var(--pc-type-small);
  font-weight: 800;
}

/* Shared single-select marker. S2 Diagnose established this radio treatment;
   later single-choice screens reuse it instead of reverting to numbered tiles. */
.pc-choice-grid--radio-marker .pc-choice-marker {
  width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--border-strong);
  border-radius: 50%;
  background: #fff;
  font-size: 0;
}

.pc-choice-grid--radio-marker .pc-choice-marker::after {
  content: "";
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: transparent;
}

.pc-choice-grid--radio-marker .pc-choice-card:has(input:checked) .pc-choice-marker::after,
.pc-choice-grid--radio-marker .pc-choice-card.selected .pc-choice-marker::after {
  background: var(--forest);
}

.pc-choice-copy {
  color: var(--ink-mid);
  line-height: 1.45;
  font-weight: 650;
}

.pc-choice-body {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--ink-mid);
  line-height: 1.5;
}

.pc-choice-body strong {
  color: var(--forest-dark);
}

.pc-selection-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  color: var(--ink-light);
  font-size: var(--pc-type-label);
  font-weight: 700;
}

.pc-button {
  min-height: 46px;
  border-radius: 9px;
  padding: 10px 17px;
  font-family: "Nunito", Arial, sans-serif;
  font-size: var(--pc-type-control);
  line-height: 1.25;
  font-weight: 800;
  cursor: pointer;
}

.pc-button--primary {
  border: 2px solid var(--forest-dark);
  background: var(--forest-dark);
  color: #fff;
}

.pc-button--primary:hover,
.pc-button--primary:focus-visible {
  background: var(--forest-mid);
  border-color: var(--forest-mid);
}

.pc-button--primary:disabled {
  opacity: .45;
  cursor: not-allowed;
}


.pc-button:focus-visible {
  outline: 4px solid rgba(196,124,45,.36);
  outline-offset: 2px;
}

.pc-feedback-card {
  margin-top: 18px;
  border-radius: 12px;
  padding: clamp(16px, 2vw, 20px);
  border: 1.5px solid var(--border);
}

.pc-feedback-card.is-strong {
  background: var(--forest-light);
  border-color: var(--forest-mid);
}

.pc-feedback-card.is-developing {
  background: var(--amber-light);
  border-color: var(--amber);
}

.pc-feedback-heading {
  color: var(--forest-dark);
  font-family: "Lora", Georgia, serif;
  font-size: var(--pc-type-card-title);
  line-height: 1.3;
  font-weight: 800;
}

.pc-feedback-card p {
  color: var(--ink-mid);
  font-size: var(--pc-type-body);
  line-height: var(--pc-leading-body);
}

.pc-feedback-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 14px;
}


/* Development shells use the same fluid scale rather than a separate one. */
.pc-scenario-shell h2 {
  font-size: var(--pc-type-mission-title);
}

.pc-shell-plan h3 {
  font-size: var(--pc-type-card-title);
}

.pc-shell-primary,
.pc-shell-secondary {
  font-size: var(--pc-type-control);
}

/* S1 uses a specialized activity, but it consumes the same type tokens. */
body.s1-active:not(.s1-result-active) #inputContainer {
  font-size: var(--pc-type-body) !important;
}

body.s1-active:not(.s1-result-active) .s1-clean-title,
body.s1-active:not(.s1-result-active) .s1-clean-builder-title {
  font-size: var(--pc-type-card-title) !important;
  line-height: 1.25 !important;
}

body.s1-active:not(.s1-result-active) .s1-clean-title--small {
  font-size: var(--pc-type-label) !important;
  margin-bottom: 7px;
}

body.s1-active:not(.s1-result-active) :is(
  .s1-clean-builder-sub,
  .s1-clean-nudge,
  .s1-clean-observed div,
  .s1-clean-prompt
) {
  font-size: var(--pc-type-body) !important;
  line-height: var(--pc-leading-body) !important;
}

body.s1-active:not(.s1-result-active) :is(
  .s1-clean-label,
  .s1-clean-ingredients .ingredient-chip
) {
  font-size: var(--pc-type-label) !important;
  line-height: 1.3 !important;
}

body.s1-active:not(.s1-result-active) .s1-clean-num {
  width: clamp(28px, 2.4vw, 34px) !important;
  height: clamp(28px, 2.4vw, 34px) !important;
  font-size: var(--pc-type-small) !important;
}

body.s1-active:not(.s1-result-active) .s1-clean-submit {
  font-size: var(--pc-type-control) !important;
  line-height: 1.25 !important;
}

/* Regular portraits may fade or slide when a line changes, but their geometry
   must follow the viewport immediately while the browser is being resized. */
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(:is(
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) :is(#vnCharacter, .vn-character, #vnStudentCharacter, .vn-student-character) {
  transition-property: opacity, transform !important;
  transition-duration: .24s !important;
  transition-timing-function: ease !important;
}

/* VN dialogue and smartboard text use one continuous scale at every width.
   Repeated IDs deliberately outrank the remaining legacy breakpoint rules. */
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) #vnSpeaker,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) .vn-speaker {
  font-size: var(--pc-type-speaker) !important;
  line-height: 1.18 !important;
}

html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) #vnText,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) .vn-text,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) .pc-feedback-copy,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.babbage-terminal-textmode) .pc-feedback-message {
  font-size: var(--pc-type-dialogue) !important;
  line-height: 1.5 !important;
}

html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active #vnAdvanceHint,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active .vn-advance,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active .prediction-continue-btn,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active #pcContinueToBabbageBtn,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active #vnPredictionChoicePanel button {
  font-size: var(--pc-type-control) !important;
}

html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-board-text,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-board-text * {
  font-size: var(--pc-type-board) !important;
  line-height: 1.24 !important;
}

html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-board-text::before,
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-board-label {
  font-size: var(--pc-type-xs) !important;
  line-height: 1.2 !important;
}

/* The standard Pixel composition uses the same fluid portrait model as the
   special intro. Width and height both participate, so short laptops no longer
   receive a tablet-sized character that covers the board. */
html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.scenario-intro-active):not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-smartboard-wrap {
  z-index: 16 !important;
}

html body #vnOverlay#vnOverlay#vnOverlay.vn-overlay.active:not(.scenario-intro-active):not(:is(
  .babbage-consult,
  .babbage-prediction,
  .pc-clean-prediction,
  .pc-prediction-question,
  .babbage-terminal-consult,
  .babbage-terminal-textmode,
  .pc-clean-output
)) .vn-board-text {
  z-index: 18 !important;
}

