  font-weight: 850;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.pc-drag-card > strong {
  color: var(--forest-dark);
  font-size: var(--pc-type-label);
  line-height: 1.3;
}
.pc-drag-card-copy {
  color: var(--ink-mid);
  font-size: var(--pc-type-small);
  line-height: 1.45;
}
.pc-drag-card-correction {
  display: block;
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px solid rgba(141, 97, 14, .22);
  color: var(--warn);
  font-size: var(--pc-type-xs);
  font-weight: 800;
}
.pc-drag-card.is-correct {
  border-color: rgba(47,113,86,.58);
  background: #f2f9f5;
}
.pc-drag-card.is-incorrect {
  border-color: rgba(141,97,14,.58);
  background: var(--gfc-gold-pale);
}

.pc-drop-zone-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 245px), 1fr));
  gap: clamp(10px, 1.4vw, 14px);
}
.pc-drop-zone,
.pc-drag-slot {
  position: relative;
  min-height: 176px;
  padding: 13px;
  border: 1.5px dashed var(--border-strong);
  border-radius: 13px;
  background: rgba(255,255,255,.68);
  transition: border-color .14s ease, background .14s ease, box-shadow .14s ease, transform .14s ease;
}
.pc-drop-zone:focus-visible,
.pc-drag-slot:focus-visible {
  outline: 4px solid rgba(230,165,29,.30);
  outline-offset: 2px;
}
.pc-drop-zone.is-targetable,
.pc-drag-slot.is-targetable {
  border-color: var(--gfc-blue-mid);
  background: var(--gfc-sky-pale);
}
.pc-drop-zone.is-drop-hover,
.pc-drag-slot.is-drop-hover {
  border-style: solid;
  border-color: var(--gfc-gold);
  background: var(--gfc-gold-pale);
  box-shadow: inset 0 0 0 2px rgba(230,165,29,.2), 0 7px 16px rgba(8,26,54,.08);
  transform: translateY(-1px);
}
.pc-drop-zone-head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
}
.pc-drop-zone-head span {
  padding: 3px 6px;
  border-radius: 5px;
  background: var(--gfc-navy);
  color: #fff;
  font-family: "Source Code Pro", monospace;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .07em;
}
.pc-drop-zone-head strong,
.pc-drag-slot-label strong {
  color: var(--forest-dark);
  font-size: var(--pc-type-label);
  line-height: 1.25;
}
.pc-drop-zone > p {
  min-height: 2.8em;
  margin: 0 0 10px;
  color: var(--ink-light);
  font-size: var(--pc-type-small);
  line-height: 1.4;
}
.pc-drop-zone-cards {
  display: grid;
  gap: 8px;
  align-content: start;
  min-height: 58px;
}
.pc-drop-zone-cards:empty::before,
.pc-drag-option-cards:empty::before {
  content: "Drop card here";
  display: grid;
  place-items: center;
  min-height: 54px;
  border: 1px dashed var(--border);
  border-radius: 9px;
  color: var(--ink-muted);
  font-size: var(--pc-type-small);
  font-weight: 700;
}

.pc-drag-slot-workbench { counter-reset: pc-drag-slot; }
.pc-drag-slot-row {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: #fff;
  overflow: hidden;
}
.pc-drag-slot-heading {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 12px;
  align-items: start;
  padding: 14px clamp(14px, 2vw, 20px);
  background: linear-gradient(90deg, var(--parchment), #fff);
  border-bottom: 1px solid var(--border);
}
.pc-drag-slot-number {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: var(--gfc-navy);
  color: #fff;
  font-family: "Source Code Pro", monospace;
  font-size: var(--pc-type-small);
  font-weight: 850;
}
.pc-drag-slot-heading h3 {
  margin: 0;
  color: var(--forest-dark);
  font-family: "Lora", Georgia, serif;
  font-size: clamp(18px, 1.7vw, 22px);
  line-height: 1.25;
}
.pc-drag-slot-heading p {
  margin: 3px 0 0;
  color: var(--ink-light);
  font-size: var(--pc-type-small);
  line-height: 1.4;
}
.pc-drag-slot-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(250px, .75fr);
  gap: 12px;
  padding: 12px;
}
.pc-drag-option-tray {
  min-width: 0;
  padding: 11px;
  border-radius: 11px;
  background: var(--parchment);
}
.pc-drag-option-tray-label,
.pc-drag-slot-label span {
  display: block;
  margin-bottom: 8px;
  color: var(--ink-light);
  font-family: "Source Code Pro", monospace;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.pc-drag-slot {
  min-height: 116px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}
.pc-drag-slot-label { margin-bottom: 8px; }
.pc-drag-slot .pc-drop-zone-cards { flex: 1 1 auto; }

.pc-drag-board.is-reviewed .pc-drag-card,
.pc-drag-slot-workbench.is-reviewed .pc-drag-card {
  cursor: default;
}
.pc-drag-board.is-reviewed .pc-drop-zone,
.pc-drag-slot-workbench.is-reviewed .pc-drag-slot {
  border-style: solid;
}

.pc-evidence-chain {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr));
  gap: 10px;
}
.pc-evidence-chain > div {
  min-width: 0;
  padding: 13px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
}
.pc-evidence-chain strong {
  display: block;
  margin-top: 6px;
  color: var(--forest-dark);
  font-size: var(--pc-type-small);
  line-height: 1.4;
}

@media screen and (max-width: 900px) {
  .pc-case-brief { grid-template-columns: 1fr; }
  .pc-case-brief-score {
    min-height: 0;
    flex-direction: row;
    justify-content: flex-start;
    gap: 10px;
    text-align: left;
  }
  .pc-case-brief-score strong { margin: 0; font-size: 38px; }
  .pc-case-brief-score small { margin-left: auto; }
  .pc-case-brief-copy {
    padding: 0 clamp(16px, 3vw, 24px) clamp(16px, 3vw, 24px);
  }
  .pc-drag-slot-layout { grid-template-columns: 1fr; }
  .pc-drag-slot { min-height: 104px; }
  .pc-drag-tray-head { align-items: flex-start; flex-direction: column; }
  .pc-drag-tray-head span { text-align: left; }
}

@media screen and (max-width: 640px) {
  .pc-case-brief-copy { grid-template-columns: 1fr; }
  .pc-case-brief-score {
    display: grid;
    grid-template-columns: auto 1fr;
  }
  .pc-case-brief-score span { grid-column: 1 / -1; }
  .pc-case-brief-score small { margin-left: 0; align-self: center; }
  .pc-drop-zone-grid { grid-template-columns: 1fr; }
  .pc-drag-tray-cards,
  .pc-drag-option-cards { grid-template-columns: 1fr; }
  .pc-drop-zone { min-height: 128px; }
  .pc-drop-zone > p { min-height: 0; }
  .pc-drag-slot-heading { padding: 12px; }
  .pc-drag-slot-layout { padding: 10px; }
  .pc-selection-bar {
    align-items: stretch;
    flex-direction: column;
  }
  .pc-selection-bar .pc-button { width: 100%; }
