/* Shared two-character VN staging. The dialogue and smartboard remain the
   ordinary S1 components. Dual-cast mode owns only two reusable character
   slots, and both slots use the same S1-resolved vertical geometry. */
@media screen and (min-width: 701px) {
  #vnOverlay.vn-overlay.active.pc-dual-character {
    --pc-vn-cast-side: clamp(10px, 2.2vw, 42px);
  }

  /* High specificity here is intentional: older S1 rules target #vnCharacter
     directly. A dual-cast scene must give both reusable slots one geometry
     owner instead of letting the original primary slot drift independently. */
  html body[data-pc-viewport-family][data-pc-viewport-family]
  #vnOverlay#vnOverlay#vnOverlay#vnOverlay.vn-overlay.active.pc-dual-character
  :is(#vnCharacter#vnCharacter, #vnStudentCharacter#vnStudentCharacter) {
    display: flex !important;
    visibility: visible !important;
    position: absolute !important;
    top: auto !important;
    bottom: var(--pc-vn-character-bottom) !important;
    width: auto !important;
    min-width: 0 !important;
    height: var(--pc-vn-character-height) !important;
    min-height: 0 !important;
    max-width: var(--pc-vn-character-max-width) !important;
    max-height: none !important;
    transform: none !important;
    align-items: flex-end !important;
    z-index: 17 !important;
    pointer-events: none !important;
    opacity: 1 !important;
    transition: filter 160ms ease !important;
  }

  html body[data-pc-viewport-family][data-pc-viewport-family]
  #vnOverlay#vnOverlay#vnOverlay#vnOverlay.vn-overlay.active.pc-dual-character
  :is(#vnCharacter#vnCharacter, #vnStudentCharacter#vnStudentCharacter)[data-pc-cast-side="left"] {
    left: var(--pc-vn-cast-side) !important;
    right: auto !important;
    justify-content: flex-start !important;
    transform-origin: left bottom !important;
  }

  html body[data-pc-viewport-family][data-pc-viewport-family]
  #vnOverlay#vnOverlay#vnOverlay#vnOverlay.vn-overlay.active.pc-dual-character
  :is(#vnCharacter#vnCharacter, #vnStudentCharacter#vnStudentCharacter)[data-pc-cast-side="right"] {
    left: auto !important;
    right: var(--pc-vn-cast-side) !important;
    justify-content: flex-end !important;
    transform-origin: right bottom !important;
  }

  #vnOverlay.vn-overlay.active.pc-dual-character
  :is(#vnCharacter, #vnStudentCharacter) > :is(#vnPortrait, #vnStudentPortrait) {
    display: block !important;
    width: auto !important;
