/* v390 — S2 learning-loop puzzle. Replaces the quiz-like diagnosis sheet. */
.s2-loop-puzzle{max-width:1040px;margin:0 auto;background:#fffdf9;border:1px solid var(--border);border-radius:14px;overflow:hidden;box-shadow:0 18px 40px rgba(48,38,27,.08)}
.s2-loop-header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:18px 28px 14px;border-bottom:1px solid var(--border);background:#fbf5eb}
.s2-loop-header h1{margin:3px 0 0;color:var(--forest-dark);font:700 clamp(25px,2.3vw,36px)/1.08 "Lora",Georgia,serif}


.s2-learning-gap{padding:24px 28px 28px;background:linear-gradient(180deg,#fffdf9,#fbf5eb)}


.s2-flow-node span{display:block;color:var(--terracotta);font:800 9px/1.2 "Source Code Pro",monospace;letter-spacing:.1em;text-transform:uppercase}

.s2-gap-flow{display:grid;grid-template-columns:1fr 36px 1fr 36px 1fr;align-items:center;gap:6px;margin-top:24px}
.s2-flow-node{min-height:112px;padding:17px 18px;border:1px solid var(--border-strong);border-radius:12px;background:#fff;display:flex;flex-direction:column;justify-content:center;text-align:center}
.s2-flow-node strong{display:block;margin:8px 0 5px;color:var(--forest-dark);font:700 clamp(18px,1.7vw,24px)/1.15 "Lora",Georgia,serif}.s2-flow-node small{color:var(--ink-light);line-height:1.3}
.s2-flow-node--missing{border:2px dashed var(--terracotta);background:#fff9ee}.s2-flow-node--missing strong{font-size:34px;color:var(--terracotta)}
.s2-flow-node--missing.is-solved{border-style:solid;border-color:var(--forest);background:#edf7f0}.s2-flow-node--missing.is-solved strong{font-size:22px;color:var(--forest-dark)}
.s2-flow-arrow{text-align:center;color:var(--forest);font-size:28px;font-weight:700}
.s2-loop-puzzle>.pc-activity-task{border:0;border-top:1px solid var(--border);border-radius:0;box-shadow:none;padding:24px 28px 28px;background:#fffdf9}
.s2-loop-puzzle>.pc-activity-task h2{max-width:760px;margin-bottom:5px}.s2-loop-puzzle>.pc-activity-task .pc-activity-instruction{max-width:780px;margin-top:0;margin-bottom:18px}
.s2-loop-puzzle .pc-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}

.s2-loop-puzzle .pc-choice-body{display:grid;gap:5px}.s2-loop-puzzle .pc-choice-body strong{color:var(--forest-dark);font-size:1rem;line-height:1.25}.s2-loop-puzzle .pc-choice-body>span{color:var(--ink-mid);font-size:.9rem;line-height:1.38}.s2-loop-puzzle .pc-selection-bar{margin-top:14px}
@media(max-width:760px){.s2-loop-header{padding:14px 16px}.s2-learning-gap{padding:18px 16px}.s2-gap-flow{grid-template-columns:1fr;gap:6px}.s2-flow-node{min-height:78px}.s2-flow-arrow{transform:rotate(90deg);font-size:20px}.s2-loop-puzzle>.pc-activity-task{padding:20px 16px}.s2-loop-puzzle .pc-choice-grid{grid-template-columns:1fr}}


