body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-quote-copy {
  min-width: 0 !important;
  width: auto !important;
  max-width: none !important;
  color: inherit !important;
  font: inherit !important;
  line-height: inherit !important;
  white-space: normal !important;
  overflow-wrap: normal !important;
  word-break: normal !important;
}

body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-quote-mark {
  color: #f4e5ba !important;
  font: 700 2.1em/.8 "Lora", Georgia, serif !important;
  opacity: .42 !important;
}

@media (max-width: 700px) {
  body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-evidence {
    grid-template-columns: 100px minmax(0, 1fr) !important;
    gap: 12px !important;
    padding: 12px !important;
  }

  body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-portrait img {
    width: 96px !important;
    height: 128px !important;
  }

  body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-label {
    font-size: .66rem !important;
  }

  body[data-pc-scenario="metacognition"] .pc-s2-babbage-draft .pc-s2-audit-jordan-quote {
    font-size: .94rem !important;
    line-height: 1.4 !important;
  }
}

/* Shared tagged-detail choice cards.
   Decision 2 established this presentation; Decision 3 and future scenarios
   reuse the same component instead of maintaining another marker/title layout. */
.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-card {
  display: grid !important;
  grid-template-columns: max-content minmax(0, 1fr) !important;
  align-items: start !important;
  column-gap: 12px !important;
  row-gap: 0 !important;
  min-height: 108px !important;
  padding: 15px 16px !important;
}

.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-marker {
  width: auto !important;
  min-width: 0 !important;
  height: auto !important;
  min-height: 28px !important;
  padding: 7px 9px !important;
  border: 1px solid var(--border-strong) !important;
  border-radius: 999px !important;
  background: var(--parchment) !important;
  font-size: .68rem !important;
  line-height: 1 !important;
  letter-spacing: .035em !important;
  white-space: nowrap !important;
}

.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-body {
  align-self: center !important;
  gap: 5px !important;
}

.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-body strong,
.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-body > span {
  min-width: 0 !important;
  overflow-wrap: anywhere !important;
}

.pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-card.selected .pc-choice-marker {
  border-color: var(--forest-mid) !important;
  background: #eef5eb !important;
}

@media (max-width: 480px) {
  .pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-card {
    grid-template-columns: 1fr !important;
    gap: 9px !important;
    min-height: 0 !important;
  }

  .pc-choice-grid.pc-choice-grid--tagged-detail .pc-choice-marker {
    justify-self: start !important;
  }
}

/* V425 — shared single-select radio marker stays consistent with S2 Diagnose. */
@media (max-width: 600px) {
  .pc-choice-grid--radio-marker .pc-choice-marker {
    width: 24px !important;
    height: 24px !important;
  }
  .pc-choice-grid--radio-marker .pc-choice-marker::after {
    width: 10px !important;
    height: 10px !important;
  }
}


/* V428 — shared completed-analysis content rows.
   Babbage diagnostics are variable-length. Keep each row sized to its content
   and give long-form rows enough separation that CRT borders never visually
   collide while the monitor owns vertical scrolling. */
html body #vnOverlay.vn-overlay.active.babbage-terminal-textmode.pc-analysis-report-active
.analysis-report-overflow-safe .analysis-grid {
  grid-auto-rows: max-content !important;
  align-items: stretch !important;
  align-content: start !important;
  row-gap: max(8px, .62em) !important;
}

html body #vnOverlay.vn-overlay.active.babbage-terminal-textmode.pc-analysis-report-active
.analysis-report-overflow-safe .analysis-card {
  height: auto !important;
  min-height: max-content !important;
  align-self: stretch !important;
  margin: 0 !important;
  position: relative !important;
}

/* V430 — completed Babbage diagnosis utility controls.
   Three actions (read, print/save, continue) share the terminal footer without
   colliding on narrow screens. Intermediate Babbage reports omit the print action. */
@media (max-width: 900px) {
  html body #vnOverlay.vn-overlay.active.babbage-terminal-textmode.pc-analysis-report-active
  .vn-dialogue #vnText:has(.babbage-print-btn) {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 5px !important;
  }

  html body #vnOverlay.vn-overlay.active.babbage-terminal-textmode.pc-analysis-report-active
  .vn-dialogue #vnText:has(.babbage-print-btn) button {
    padding-inline: 4px !important;
    font-size: clamp(0.62rem, 2.75vw, 0.78rem) !important;
  }
}

/* SOURCE: src/css/ui/gfc-theme.css */
/* ══════════════════════════════════════════════════════
   PROMPTCRAFT · GREAT FALLS COLLEGE VISUAL THEME
   Visual skin only. Layout, game loop, scenario state, and Babbage's retro
   terminal language remain owned by their existing components.
   ══════════════════════════════════════════════════════ */

:root {
  --gfc-navy: #112650;
  --gfc-navy-deep: #081a36;
  --gfc-blue: #086c9f;
  --gfc-blue-mid: #2c8dbe;
  --gfc-sky: #59b7e3;
  --gfc-sky-pale: #e9f5fb;
  --gfc-gold: #e6a51d;
  --gfc-gold-dark: #98670d;
  --gfc-gold-pale: #fff4d5;

  /* Map the existing shared PromptCraft token vocabulary onto the campus skin. */
  --cream: #fbfaf6;
  --parchment: #f2f5f6;
  --parchment-drk: #e4eaed;
  --chalk: #fffdfa;
  --forest: var(--gfc-blue);
  --forest-light: var(--gfc-sky-pale);
  --forest-mid: var(--gfc-blue-mid);
  --forest-dark: var(--gfc-navy);
  --terracotta: #c77f10;
  --terra-light: #fff5df;
  --terra-dark: #8b5708;
  --amber: var(--gfc-gold);
  --amber-light: var(--gfc-gold-pale);
  --amber-dark: var(--gfc-gold-dark);
  --chalkboard: var(--gfc-navy);
  --chalk-white: #f8fbfd;
  --chalk-green: var(--gfc-sky);
  --ink: #1e2834;
  --ink-mid: #3e4b58;
  --ink-light: #687987;
  --ink-muted: #8d9aa5;
  --border: #d5dde2;
  --border-light: #e8edf0;
  --border-strong: #aebbc4;
  --good: #2f7156;
  --warn: #8d610e;
  --ref-paper: #f8f8f5;
  --ref-border: #cdd7dd;
  --ref-ink: #202b37;
  --ref-ink-mid: #3e4b58;
  --ref-input-bdr: #afbdc7;

  --pc-a11y-ink: #182330;
  --pc-a11y-ink-mid: #344351;
  --pc-a11y-forest: #0b527b;
  --pc-a11y-forest-dark: #091f3f;
  --pc-a11y-border: #8797a3;
  --pc-a11y-panel: #fffdfa;
  --pc-a11y-bg: #f2f5f6;
}

body {
  background-color: var(--cream);
  background-image:
    radial-gradient(ellipse at 12% 8%, rgba(89, 183, 227, 0.08), transparent 48%),
    radial-gradient(ellipse at 88% 92%, rgba(230, 165, 29, 0.055), transparent 50%);
  color: var(--ink);
}

/* ── Persistent app chrome ─────────────────────────── */
.dev-bar {
  background: var(--gfc-navy-deep) !important;
  border-bottom-color: rgba(89, 183, 227, 0.75) !important;
}
.dev-bar span,
.dev-btn { color: #dceff8 !important; }
.dev-btn { border-color: rgba(89, 183, 227, 0.72) !important; }
.dev-btn:hover,
.dev-btn:focus-visible {
  background: var(--gfc-blue) !important;
  border-color: var(--gfc-sky) !important;
  color: #fff !important;
}

header.pc-app-header {
  background: linear-gradient(105deg, var(--gfc-navy-deep), var(--gfc-navy) 72%, #14345f) !important;
  border-bottom-color: var(--gfc-gold) !important;
  box-shadow: 0 4px 16px rgba(8, 26, 54, 0.18);
}
.logo-icon,
.pc-brand-summary .logo-icon {
  background: #0b5f8d !important;
  border-color: rgba(230, 165, 29, 0.9) !important;
}
.logo-name,
.logo-name span { color: #fff !important; }
.logo-name span { color: var(--gfc-sky) !important; }
.logo-sub { color: #d9eaf3 !important; }
.pc-brand-caret { color: #d9eaf3 !important; }
.level-tag {
  background: rgba(89, 183, 227, 0.12) !important;
  border-color: rgba(89, 183, 227, 0.62) !important;
  color: #f4fbff !important;
}
.xp-label { color: #cfe5f0 !important; }
.xp-fill { background: linear-gradient(90deg, var(--gfc-sky), var(--gfc-gold)) !important; }
.music-toggle,
.main-menu-toggle,
.ideas-wall-btn {
  border-color: rgba(89, 183, 227, 0.46) !important;
  color: #f7fbfd !important;
}
.main-menu-toggle:hover,
.main-menu-toggle:focus-visible,
.music-toggle:hover,
.music-toggle:focus-visible,
.ideas-wall-btn:hover,
.ideas-wall-btn:focus-visible {
  background: rgba(89, 183, 227, 0.15) !important;
  border-color: var(--gfc-sky) !important;
}
.ideas-wall-btn { box-shadow: inset 0 -2px 0 rgba(230, 165, 29, 0.5); }

.scenario-tabs {
  background: #f4f3ed !important;
  border-bottom-color: #c6d1d7 !important;
}
.tab-btn { color: #344351 !important; }
.tab-btn:hover { color: var(--gfc-blue) !important; }
.tab-btn.active {
  color: var(--gfc-navy) !important;
  border-bottom-color: var(--gfc-gold) !important;
  background: rgba(89, 183, 227, 0.12) !important;
}

/* Native compact navigation mirrors the same palette on phones. */
@media screen and (max-width: 640px) {
  html body .pc-compact-nav {
    border-color: #b6c3cb !important;
    background: #eef3f5 !important;
  }
  html body .pc-compact-nav > .mobile-compact-menu > summary.mobile-dropdown-toggle {
    border-color: var(--gfc-navy) !important;
    background: var(--gfc-blue) !important;
    color: #fff !important;
  }
  html body .pc-compact-nav .mobile-dropdown-panel {
    border-color: #aabac4 !important;
    background: #fffdfa !important;
  }
  html body .pc-compact-nav .mobile-dropdown-option:hover,
  html body .pc-compact-nav .mobile-dropdown-option:focus-visible,
  html body .pc-compact-nav .mobile-dropdown-option.is-active {
    background: var(--gfc-sky-pale) !important;
    color: var(--gfc-navy) !important;
  }
}

/* ── Brand dropdown ────────────────────────────────── */
html body .pc-brand-menu[open] .pc-brand-summary {
  border-color: rgba(89, 183, 227, 0.6) !important;
}
html body .pc-brand-menu-panel {
  border-color: rgba(89, 183, 227, 0.8) !important;
  background: #0b2142 !important;
  box-shadow: 0 16px 34px rgba(4, 15, 31, 0.46) !important;
}
html body .pc-brand-menu-item {
  border-color: rgba(89, 183, 227, 0.38) !important;
  background: #12335d !important;
  color: #fff !important;
}
html body .pc-brand-menu-item:hover,
html body .pc-brand-menu-item:focus-visible {
  background: #174b78 !important;
  border-color: var(--gfc-sky) !important;
}
html body .pc-brand-menu-ideas {
  background: #72520b !important;
  border-color: var(--gfc-gold) !important;
}
html body .pc-brand-menu-ideas:hover,
html body .pc-brand-menu-ideas:focus-visible { background: #8a6511 !important; }

/* ── Main menu ─────────────────────────────────────── */
.pc-main-menu-backdrop {
  background:
    radial-gradient(circle at 18% 18%, rgba(89, 183, 227, 0.19), transparent 38%),
    linear-gradient(145deg, rgba(5, 22, 46, 0.975), rgba(17, 38, 80, 0.985)) !important;
}
.pc-main-menu-shell {
  border-color: rgba(89, 183, 227, 0.55) !important;
  background: linear-gradient(rgba(251,250,246,.99), rgba(241,245,247,.99)), var(--cream) !important;
}
.pc-main-menu-topbar {
  background: linear-gradient(100deg, var(--gfc-navy-deep), var(--gfc-navy)) !important;
  border-bottom-color: var(--gfc-gold) !important;
}
.pc-main-menu-kicker,
.pc-menu-eyebrow { color: var(--gfc-blue) !important; }
.pc-main-menu-topbar .pc-main-menu-kicker { color: var(--gfc-sky) !important; }
.pc-main-menu-affiliation {
  display: block;
  margin-top: 4px;
  color: #d8e9f2;
  font: 700 0.62rem/1.2 "Source Code Pro", ui-monospace, monospace;
  letter-spacing: .095em;
  text-transform: uppercase;
}
.pc-main-menu-close {
  border-color: rgba(89,183,227,.65) !important;
  color: #fff !important;
}
.pc-main-menu-close:hover,
.pc-main-menu-close:focus-visible { background: rgba(89,183,227,.15) !important; }
.pc-menu-home-copy h2,
.pc-menu-panel-heading h2 { color: #1d2733 !important; }
.pc-menu-action {
  border-color: var(--gfc-blue) !important;
  color: var(--gfc-navy) !important;
}
.pc-menu-action-primary {
  background: var(--gfc-blue) !important;
  border-color: var(--gfc-navy) !important;
  color: #fff !important;
  box-shadow: inset 0 -3px 0 rgba(8,26,54,.25), 0 4px 10px rgba(8,26,54,.12);
}
.pc-menu-action:hover,
.pc-menu-action:focus-visible {
  box-shadow: 0 0 0 3px rgba(89,183,227,.2) !important;
}
.pc-menu-action-primary:hover,
.pc-menu-action-primary:focus-visible { background: #075e8a !important; }
.pc-menu-secondary-actions button { color: var(--gfc-navy) !important; }
.pc-menu-secondary-actions button:hover,
.pc-menu-secondary-actions button:focus-visible { color: var(--gfc-blue) !important; }
.pc-menu-data-summary {
  border-color: #c99324 !important;
  background: #fff6e4 !important;
}
.pc-menu-data-summary h3,
.pc-menu-data-summary button { color: #7e5005 !important; }
.pc-menu-scenario-card {
  border-color: #8a9aa5 !important;
  background: #fff !important;
}
.pc-menu-scenario-card:hover,
.pc-menu-scenario-card:focus-visible {
  border-color: var(--gfc-blue) !important;
  box-shadow: 0 5px 14px rgba(8, 62, 94, 0.15) !important;
}
.pc-menu-scenario-card:focus-visible { outline-color: var(--gfc-gold) !important; }
.pc-menu-scenario-number { background: var(--gfc-navy) !important; color: #fff !important; }
.pc-menu-scenario-title,
.pc-menu-info-grid h3 { color: var(--gfc-navy) !important; }
.pc-menu-scenario-card.is-current {
  border-color: var(--gfc-gold-dark) !important;
  background: #fff8e9 !important;
}
.pc-menu-scenario-card.is-current .pc-menu-scenario-status {
  background: #f7e1aa !important;
  color: #704804 !important;
}
.pc-menu-scenario-card.is-complete {
  border-color: var(--gfc-blue) !important;
  background: var(--gfc-sky-pale) !important;
}
.pc-menu-scenario-card.is-complete .pc-menu-scenario-status {
  background: #cfeaf6 !important;
  color: #0b4f75 !important;
}
.pc-main-menu-footer {
  border-top-color: #a9b7c0 !important;
  background: #e8edef !important;
  color: #344351 !important;
}
.pc-menu-qr-card {
  border-color: var(--gfc-blue) !important;
  background: linear-gradient(145deg, #0c3158, var(--gfc-navy)) !important;
}
.pc-menu-qr-kicker { color: var(--gfc-sky) !important; }

/* ── Scenario workspaces ───────────────────────────── */
.s1-clean-stage { background: #fbfaf6 !important; }
.s1-clean-mission,
.scenario-mission {
  background: linear-gradient(120deg, var(--gfc-navy), #0c5f8d) !important;
  border-color: var(--gfc-navy-deep) !important;
  box-shadow: 0 8px 22px rgba(8,38,72,.17) !important;
}
.s1-clean-mission .mission-eyebrow,
.scenario-mission .mission-eyebrow { color: #bfe8f8 !important; }
.s1-clean-mission .mission-copy,
.scenario-mission .mission-copy { color: #eef8fc !important; }
.s1-clean-card,
.s1-clean-builder,
.pc-activity-card,
.pc-panel {
  border-color: #aab8c1 !important;
  box-shadow: 0 6px 16px rgba(24,43,58,.07) !important;
}
.s1-clean-eyebrow { color: #a96706 !important; }
.s1-clean-builder-title,
.s1-clean-title { color: var(--gfc-navy) !important; }
.s1-clean-prompt,
.s1-clean-textarea { border-color: #aebbc4 !important; }
.s1-clean-textarea:focus {
  border-color: var(--gfc-blue-mid) !important;
  box-shadow: 0 0 0 3px rgba(44,141,190,.14), inset 0 1px 3px rgba(26,39,52,.04) !important;
}
.s1-clean-num { background: var(--gfc-navy) !important; color: #dff2fb !important; }
.s1-clean-submit,
.continue-btn,
.pc-primary-action {
  border-color: var(--gfc-navy) !important;
  background: var(--gfc-blue) !important;
  color: #fff !important;
  box-shadow: 0 4px 10px rgba(8,54,84,.17) !important;
}
.s1-clean-submit:hover,
.s1-clean-submit:focus,
.continue-btn:hover,
.continue-btn:focus-visible,
.pc-primary-action:hover,
.pc-primary-action:focus-visible { background: var(--gfc-navy) !important; }
.s1-clean-ingredients { background: #eef3f5 !important; }
.s1-clean-observed div {
  background: #fff5df !important;
  border-color: rgba(198,128,17,.36) !important;
}
.s1-clean-observed strong { color: #875608 !important; }
.s1-clean-nudge { background: #fff4d5 !important; border-color: #d39b23 !important; }

/* ── VN world: real GFC rooms, same VN/game geometry ── */
.vn-overlay { background: #071321 !important; }
.vn-scene { background: var(--gfc-navy-deep) !important; }
.vn-scene::before {
  background:
    linear-gradient(to bottom, rgba(5,20,38,.20), rgba(5,20,38,.43)),
    radial-gradient(circle at 28% 28%, rgba(89,183,227,.06), transparent 32%) !important;
}
.vn-bg {
  opacity: .72 !important;
  filter: brightness(.68) saturate(.92) contrast(1.02) !important;
}
.vn-screen {
  background: #061625 !important;
  box-shadow:
    0 0 0 2px rgba(0,0,0,.45),
    inset 4px 4px 12px rgba(0,0,0,.7),
    inset -1px -1px 6px rgba(0,0,0,.3),
    0 0 0 4px rgba(89,183,227,.08),
    0 0 24px rgba(89,183,227,.17),
    0 0 56px rgba(8,108,159,.10) !important;
}
.vn-screen::before {
  background: linear-gradient(160deg, rgba(5,20,38,.56) 0%, rgba(5,20,38,.12) 45%, rgba(5,20,38,.76) 100%) !important;
}
.vn-screen-inner-border { border-color: rgba(89,183,227,.3) !important; }
.vn-board-label { color: rgba(179,226,246,.92) !important; }
.vn-board-label::before {
  background: var(--gfc-gold) !important;
  box-shadow: 0 0 8px rgba(230,165,29,.8), 0 0 16px rgba(230,165,29,.4) !important;
}
.vn-board-loading { color: rgba(179,226,246,.75) !important; }
.vn-dialogue::before,
.vn-dialogue::after { border-color: rgba(89,183,227,.62) !important; }
.vn-speaker,
.vn-advance { color: #bde8f8 !important; }
.vn-cursor { background: var(--gfc-sky) !important; }
.vn-skip {
  border-color: rgba(89,183,227,.52) !important;
  color: #c9edf9 !important;
}
.vn-skip:hover { border-color: var(--gfc-sky) !important; }
.vn-control-rail { border-bottom: 2px solid rgba(230,165,29,.45); }
.vn-brand { color: rgba(17,38,80,.55) !important; }
.vn-brand-menu .logo-icon { color: #fff !important; }

/* Focus is a campus-gold signal across light and dark surfaces. */
:focus-visible { outline-color: var(--gfc-gold) !important; }
.vn-overlay :focus-visible { outline-color: var(--gfc-sky) !important; }

/* Babbage is intentionally NOT recolored here. Its green CRT language is a
   distinct machine state, not an institutional surface. */

/* ── High-specificity cleanup for legacy green owners ────────────
   These rules intentionally live at the very end of the cascade. Older
   accessibility/responsive owners use !important with scenario-qualified
   selectors, so the GFC theme must match or exceed that specificity rather
   than changing the underlying layout rules. */
html body > .dev-bar,
html body .dev-bar {
  background: var(--gfc-navy-deep) !important;
  border-bottom-color: rgba(89,183,227,.7) !important;
  color: #eef8fc !important;
}
html body .dev-bar .dev-label,
html body .dev-bar .dev-btn,
html body .dev-bar button,
html body .dev-bar span {
  color: #eef8fc !important;
  border-color: rgba(183,228,247,.58) !important;
}
html body .dev-bar .dev-btn:hover,
html body .dev-bar .dev-btn:focus-visible,
html body .dev-bar button:hover,
html body .dev-bar button:focus-visible {
  background: rgba(89,183,227,.14) !important;
  border-color: var(--gfc-sky) !important;
}

html body.s1-active:not(.s1-result-active) .s1-clean-mission {
  background: linear-gradient(120deg, var(--gfc-navy), #0c5f8d) !important;
  border-color: var(--gfc-navy-deep) !important;
  box-shadow: 0 8px 22px rgba(8,38,72,.17) !important;
}
html body.s1-active:not(.s1-result-active) .s1-clean-mission .mission-eyebrow {
  color: #bfe8f8 !important;
}
html body.s1-active:not(.s1-result-active) .s1-clean-mission .mission-copy {
  color: #eef8fc !important;
}
html body.s1-active:not(.s1-result-active) .s1-clean-builder-title {
