/* v455 — shared drag-board completion feedback.
   Controls remain responsive while incomplete and become visually ready when
   every required card/slot has been populated. */
.pc-drag-activity .pc-selection-bar .pc-button.is-not-ready {
  opacity: .78;
  filter: saturate(.72);
  cursor: pointer;
}
.pc-drag-board.needs-more + .pc-selection-bar,
.pc-drag-slot-workbench.needs-more + .pc-selection-bar {
  border-color: rgba(183, 111, 16, .48);
}
.pc-drag-board.needs-more + .pc-selection-bar [role="status"],
.pc-drag-slot-workbench.needs-more + .pc-selection-bar [role="status"] {
  color: #8a4d0a;
  font-weight: 800;
}
.pc-drag-board.is-complete + .pc-selection-bar .pc-button,
.pc-drag-slot-workbench.is-complete + .pc-selection-bar .pc-button {
  opacity: 1;
  filter: none;
}


/* v456 — progressive evidence sorting. Correct cards persist between checks so
   the board itself communicates what the player has already established. */
.pc-drag-card.is-correct[data-pc-card-locked="true"] {
  padding-right: 82px;
  border-color: rgba(47,113,86,.78);
  background: #edf8f1;
  box-shadow: inset 0 0 0 1px rgba(47,113,86,.08);
  cursor: default;
}
.pc-drag-card.is-correct[data-pc-card-locked="true"]::after {
  content: "✓ Correct";
  position: absolute;
  top: 9px;
  right: 9px;
  padding: 3px 6px;
  border-radius: 999px;
  background: rgba(47,113,86,.12);
  color: #246246;
  font-family: "Source Code Pro", monospace;
  font-size: 9.5px;
  line-height: 1.2;
  font-weight: 850;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.pc-drag-card.is-correct[data-pc-card-locked="true"]:hover {
  transform: none;
  box-shadow: inset 0 0 0 1px rgba(47,113,86,.08);
}


/* v460 — S2/S3 shared scenario-shell alignment.
   Scenario 2 now inherits the same centered stage, Student Evidence proportions,
   and context-card rhythm used by S3. S2 keeps its metacognition mechanics; only
   the scenario shell is shared. This also prevents the Diagnose context from
   displaying the missing-link answer before the player chooses it. */
body[data-pc-scenario="metacognition"] .pc-scenario-stage {
  position: static !important;
  left: auto !important;
  width: min(100%, 1500px) !important;
  max-width: 1500px !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding: var(--pc-stage-pad-block) var(--pc-stage-pad-inline) clamp(28px, 4vw, 44px) !important;
  transform: none !important;
}

body[data-pc-scenario="metacognition"] .pc-s2-case-brief {
  padding: 0 !important;
  background: linear-gradient(135deg, #fffdfa 0%, var(--parchment) 100%) !important;
  box-shadow: 0 10px 24px rgba(8, 26, 54, .07) !important;
}

/* The mission briefing already names the case. S3 does not repeat a second case
   title between Student Evidence and context, so S2 now follows the same shell. */
body[data-pc-scenario="metacognition"] .pc-s2-case-header {
  display: none !important;
}

body[data-pc-scenario="metacognition"] .pc-s2-case-brief .pc-case-brief-copy {
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: clamp(12px, 2vw, 22px) !important;
  padding: clamp(18px, 2.4vw, 28px) clamp(18px, 2.8vw, 34px) !important;
}

/* Decision 1 asks the player to identify this missing link. Keep it out of the
   pre-decision context rather than quietly displaying the answer first. */
body[data-pc-scenario="metacognition"] .pc-s2-case-brief .pc-case-brief-copy > div:nth-child(3) {
  display: none !important;
}

@media (max-width: 900px) {
  body[data-pc-scenario="metacognition"] .pc-s2-case-brief .pc-case-brief-copy {
    grid-template-columns: 1fr !important;
  }
